FUND DOCUMENTS (IM, Mandate):
${JSON.stringify($json.documents)}

ASSET CLASS: ${$json.ra03_report || 'Not available'}

INVESTMENT MANAGER BACKGROUND:
${$json.ra01_report || 'Not available'}

RA-03 ASSET CLASS RESEARCH:
${$json.ra03_report || 'Not available'}

RA-04 LEGAL COUNSEL ASSESSMENT:
${$json.ra04_report || 'Not available'}

RA-05 INFRASTRUCTURE ASSESSMENT:
${$json.ra05_report || 'Not applicable'}

KYC RESULT:
${JSON.stringify($json.kyc_result)}

Return a JSON object with these required fields: mandate_summary (string), asset_class_assessment (string), investment_manager_assessment (string), legal_structure_assessment (string), infrastructure_assessment (string), risk_rating (enum: Low | Medium | High | Decline), key_concerns (array of strings), mandate_fit_conclusion (string).` }] }], generationConfig: { temperature: 0, maxOutputTokens: 4096, responseMimeType: 'application/json' } }) }}

parameters.jsCode:
const response = $input.first().json;
const text = response.candidates?.[0]?.content?.parts?.[0]?.text;

let fundRiskSummary = null;
if (text) {
  try {
    const cleaned = text.replace(/^```json\n?|```$/gm, '').trim();
    fundRiskSummary = JSON.parse(cleaned);
  } catch (e) {
    console.warn('CR-05: Could not parse Gemini response as JSON.');
  }
}
if (!fundRiskSummary) {
  fundRiskSummary = { raw_response: response, extraction_failed: true };
}

const caseData = $('Postgres: Aggregate DD Inputs').first().json;
return [{ json: { ...caseData, fund_risk_summary: fundRiskSummary, cr05_raw_response: response } }];

parameters.query:
SELECT bundle_key, content
FROM car_policy_bundles
WHERE bundle_key IN (
    'cr03_core',
    'cr03_risk_taxonomy'
    {{ $json.applicant_type === 'Fund' ? ", 'cr03_fund_addon'" : '' }}
);

parameters.jsCode:
const caseData = $('Code: Merge Branches').first().json;
const bundles = {};
for (const row of $input.all()) {
  bundles[row.json.bundle_key] = row.json.content;
}

const missing = ['cr03_core', 'cr03_risk_taxonomy'].filter(k => !bundles[k]);
if (caseData.applicant_type === 'Fund' && !bundles['cr03_fund_addon']) missing.push('cr03_fund_addon');
if (missing.length > 0) {
  throw new Error(`CR-03: missing required policy bundle(s): ${missing.join(', ')}. Populate car_policy_bundles before running this workflow — see SETUP.md.`);
}

// --- authorisation_sought extraction (PLAN.md rule: never default downward to 'general') ---
const intake = caseData.intake_data || {};
let authorisationSought = intake.authorisation_sought || intake.section_4a || null;
let authorisationAssumed = false;
if (!authorisationSought || !authorisationSought.advice_type) {
  authorisationSought = {
    advice_type: 'personal_wholesale',
    client_class: authorisationSought?.client_class || 'wholesale',
    service_types: authorisationSought?.service_types || ['advice'],
    product_classes: authorisationSought?.product_classes || []
  };
  authorisationAssumed = true;
}

// --- Block 1: role and methodology (verbatim from PLAN.md) ---
const block1 = `You are Alpha Node's senior compliance analyst producing a formal Due Diligence report on an applicant for an AR, CAR, or Fund authorisation.\n\nYour output will be reviewed by senior staff, may be inspected by ASIC if a complaint arises, and forms part of the firm's permanent compliance record. Apply the standard of care that implies.\n\nMethodology:\n1. Read all inputs. Cross-reference claims with verifying sources. Where claims are unverified, mark as outstanding.\n2. Identify red flags (blocking concerns) and orange flags (proceed-with-attention concerns) explicitly. Do not bury them in narrative.\n3. For individuals: apply the fit-and-proper test (competence, honesty/integrity, financial soundness).\n4. For funds: assess mandate viability, structural transparency, asset class risk, infrastructure readiness, conflicts, insurance/tax, and in-house expertise.\n5. Apply Alpha Node policy context (Block 3) to assess alignment.\n6. Produce a recommended decision with reasoning that a regulator could follow.\n7. List supervision recommendations specific to the identified risks of this applicant.\n8. State the authorisation type sought (advice_type x client_class x service_types x product_classes) at the very top of the executive_summary field, before any biographical information. Calibrate the entire competence and qualification analysis against this scope. Do not assume general advice if the input says personal advice.\n9. Cite the source of every factual claim in the executive_summary inline using square-bracket notation (e.g. [Application Form S1], [RA-01], [Kaplan Certificate]). The opening biographical paragraph must be fully sourced. Do not state facts without attribution.\n10. Distinguish verified facts from assumed undertakings. A fact belongs in rationale or fit-and-proper narrative. An assumed undertaking belongs in the assumed_undertakings array, not in rationale as if already established. Never treat an assumed undertaking as a verified constraint on the applicant's behaviour.\n\nBe specific. Avoid hedging language unless genuine uncertainty exists. Cite the source of each finding.`;

const block2 = bundles['cr03_risk_taxonomy'];
let block3 = bundles['cr03_core'];
if (caseData.applicant_type === 'Fund') block3 += '\n\n' + bundles['cr03_fund_addon'];

const systemPrompt = `${block1}\n\n---\nRISK TAXONOMY:\n${block2}\n\n---\nALPHA NODE POLICY CONTEXT:\n${block3}`;

// --- User prompt: structured DD inputs ---
const userPrompt = `# DD Inputs for Case ${caseData.applicant_id}\n\n## Applicant Type: ${caseData.applicant_type}\n## Licence Target: ${caseData.licence_target || 'Not specified'}\n## Authorisation Sought${authorisationAssumed ? ' (ASSUMED — not explicit in intake, defaulted to the conservative personal_wholesale standard)' : ''}:\n${JSON.stringify(authorisationSought)}\n\n## 1. Intake Data\n${JSON.stringify(caseData.intake_data)}\n\n## 2. Documents Received\n${JSON.stringify(caseData.documents)}\n\n## 3. KYC Result\n${JSON.stringify(caseData.kyc_result)}\n\n## 4. Reference Analysis (CR-02 Output)\n${JSON.stringify(caseData.reference_analysis)}\n\n## 5. Meeting Analyses (CR-01 Outputs)\n${JSON.stringify(caseData.meeting_analyses)}\n\n## 6. Research Agent Reports\n### RA-01 Individual Background\n${caseData.ra01_report || 'Not applicable'}\n### RA-02 Company Research\n${caseData.ra02_report || 'Not applicable'}\n### RA-03 Fund Asset Class Research\n${caseData.ra03_report || 'Not applicable'}\n### RA-04 Legal Counsel Assessment\n${caseData.ra04_report || 'Not applicable'}\n### RA-05 Infrastructure Research\n${caseData.ra05_report || 'Not applicable'}\n### RA-06 Background Checks\n${caseData.ra06_report || 'Not applicable'}\n\n## 7. Fund Mandate Risk Summary (CR-05 Output)\n${caseData.fund_risk_summary ? JSON.stringify(caseData.fund_risk_summary) : 'Not applicable'}\n\n---\nNow produce the DD report using the submit_dd_report tool.`;

// --- submit_dd_report tool schema, cleaned for Gemini's OpenAPI-subset function-calling format ---
// (type unions like ["string","null"] become nullable: true; otherwise matches PLAN.md's tool definition)
const submitDdReportSchema = {
  name: 'submit_dd_report',
  description: 'Submit the structured DD report for senior staff review',
  parameters: {
    type: 'object',
    properties: {
      executive_summary: { type: 'string' },
      risk_rating: { type: 'string', enum: ['low', 'medium', 'high', 'decline'] },
      recommended_decision: { type: 'string', enum: ['proceed', 'proceed_with_conditions', 'decline'] },
      rationale: { type: 'string' },
      fit_and_proper_assessment: {
        type: 'object',
        nullable: true,
        properties: {
          overall: { type: 'string', enum: ['satisfied', 'satisfied_with_conditions', 'not_satisfied'] },
          competence: { type: 'string' },
          honesty_and_integrity: { type: 'string' },
          financial_soundness: { type: 'string' }
        }
      },
      fund_specific_findings: {
        type: 'object',
        nullable: true,
        properties: {
          mandate_viability: { type: 'string' },
          structural_transparency: { type: 'string' },
          asset_class_risk: { type: 'string' },
          infrastructure_readiness: { type: 'string' },
          conflicts_of_interest: { type: 'string' },
          insurance_and_tax_position: { type: 'string' },
          in_house_expertise_assessment: { type: 'string' }
        }
      },
      red_flags: {
        type: 'array',
        items: {
          type: 'object',
          properties: {
            flag: { type: 'string' },
            source: { type: 'string' },
            severity: { type: 'string', enum: ['minor', 'moderate', 'serious', 'blocking'] },
            evidence: { type: 'string' },
            mitigation: { type: 'string', nullable: true }
          },
          required: ['flag', 'source', 'severity', 'evidence']
        }
      },
      orange_flags: {
        type: 'array',
        items: {
          type: 'object',
          properties: { flag: { type: 'string' }, source: { type: 'string' }, evidence: { type: 'string' } }
        }
      },
      outstanding_items: { type: 'array', items: { type: 'string' } },
      conditions: {
        type: 'array',
        items: {
          type: 'object',
          properties: {
            severity: { type: 'string', enum: ['critical', 'high', 'medium', 'low'] },
            condition: { type: 'string' },
            owner: { type: 'string', enum: ['applicant', 'alphanode'] },
            deadline: { type: 'string' },
            finding_link: { type: 'string', nullable: true }
          },
          required: ['severity', 'condition', 'owner', 'deadline']
        }
      },
      supervision_recommendations: { type: 'array', items: { type: 'string' } },
      assumed_undertakings: {
        type: 'array',
        items: {
          type: 'object',
          properties: {
            undertaking: { type: 'string' },
            source: { type: 'string', enum: ['CR-01_meeting', 'Form03_Section12', 'both'] },
            effective_date: { type: 'string', nullable: true },
            breach_consequence: { type: 'string' }
          },
          required: ['undertaking', 'source']
        }
      },
      sources_reviewed: {
        type: 'array',
        items: {
          type: 'object',
          properties: {
            id: { type: 'string' },
            title: { type: 'string' },
            date: { type: 'string', nullable: true },
            type: { type: 'string', enum: ['internal_ra', 'client_document', 'public_register', 'regulator_record', 'court_or_tribunal', 'professional_record', 'media_or_web', 'policy', 'other'] },
            summary: { type: 'string' },
            file: { type: 'string', nullable: true },
            url: { type: 'string', nullable: true },
            used_by: { type: 'array', items: { type: 'string' } }
          },
          required: ['id', 'title', 'type', 'summary']
        }
      }
    },
    required: ['executive_summary', 'risk_rating', 'recommended_decision', 'rationale', 'red_flags', 'orange_flags', 'outstanding_items', 'supervision_recommendations', 'sources_reviewed']
  }
};

const geminiRequest = {
  systemInstruction: { parts: [{ text: systemPrompt }] },
  contents: [{ role: 'user', parts: [{ text: userPrompt }] }],
  tools: [{ functionDeclarations: [submitDdReportSchema] }],
  toolConfig: { functionCallingConfig: { mode: 'ANY', allowedFunctionNames: ['submit_dd_report'] } },
  generationConfig: { temperature: 0, maxOutputTokens: 12000 }
};

return [{ json: { ...caseData, authorisation_sought: authorisationSought, authorisation_assumed: authorisationAssumed, geminiRequest, attempt: 1 } }];

const caseData = $('Code: Build Full CR-03 Prompt').first().json;
const response = $input.first().json;
const part = response.candidates?.[0]?.content?.parts?.find(p => p.functionCall);
const args = part?.functionCall?.args;

const errors = [];
if (!args) {
  errors.push('No submit_dd_report function call returned by the model.');
} else {
  if (args.risk_rating === 'decline' !== (args.recommended_decision === 'decline')) errors.push('risk_rating=decline must match recommended_decision=decline (and vice versa).');
  if (args.recommended_decision === 'proceed_with_conditions' && !(args.conditions && args.conditions.length > 0)) errors.push('recommended_decision=proceed_with_conditions requires a non-empty conditions array.');
  if (caseData.applicant_type === 'Individual' && !args.fit_and_proper_assessment) errors.push('applicant_type=Individual requires fit_and_proper_assessment.');
  if (caseData.applicant_type === 'Fund' && !args.fund_specific_findings) errors.push('applicant_type=Fund requires fund_specific_findings.');
  if ((args.red_flags || []).some(f => !f.evidence)) errors.push('Every red flag requires non-empty evidence.');
  if (!args.executive_summary || args.executive_summary.length < 200 || args.executive_summary.length > 1500) errors.push('executive_summary must be between 200 and 1500 characters.');
  if ((caseData.meeting_analyses || []).length === 0 && caseData.applicant_type === 'Individual') errors.push('No meeting_analyses present for an Individual applicant — this should have been caught at submit time.');
}

return [{
  json: {
    ...caseData,
    dd_report: args || null,
    cr03_raw_response: response,
    valid: errors.length === 0,
    validation_errors: errors,
    input_token_count: response.usageMetadata?.promptTokenCount || null,
    output_token_count: response.usageMetadata?.candidatesTokenCount || null
  }
}];

const prev = $input.first().json;
const correctivePrompt = `Your previous submit_dd_report call failed validation for these reasons:\n${prev.validation_errors.map(e => '- ' + e).join('\n')}\n\nCall submit_dd_report again, correcting these issues. Do not repeat the same mistakes.`;

const request = JSON.parse(JSON.stringify(prev.geminiRequest));
request.contents.push({ role: 'model', parts: [{ functionCall: { name: 'submit_dd_report', args: prev.dd_report || {} } }] });
request.contents.push({ role: 'user', parts: [{ text: correctivePrompt }] });

return [{ json: { ...prev, geminiRequest: request, attempt: 2 } }];

const caseData = $('Code: Build Corrective Retry Prompt').first().json;
const response = $input.first().json;
const part = response.candidates?.[0]?.content?.parts?.find(p => p.functionCall);
const args = part?.functionCall?.args;

const errors = [];
if (!args) {
  errors.push('No submit_dd_report function call returned by the model on retry.');
} else {
  if (args.risk_rating === 'decline' !== (args.recommended_decision === 'decline')) errors.push('risk_rating=decline must match recommended_decision=decline (and vice versa).');
  if (args.recommended_decision === 'proceed_with_conditions' && !(args.conditions && args.conditions.length > 0)) errors.push('recommended_decision=proceed_with_conditions requires a non-empty conditions array.');
  if (caseData.applicant_type === 'Individual' && !args.fit_and_proper_assessment) errors.push('applicant_type=Individual requires fit_and_proper_assessment.');
  if (caseData.applicant_type === 'Fund' && !args.fund_specific_findings) errors.push('applicant_type=Fund requires fund_specific_findings.');
  if ((args.red_flags || []).some(f => !f.evidence)) errors.push('Every red flag requires non-empty evidence.');
  if (!args.executive_summary || args.executive_summary.length < 200 || args.executive_summary.length > 1500) errors.push('executive_summary must be between 200 and 1500 characters.');
}

return [{
  json: {
    ...caseData,
    dd_report: args || null,
    cr03_raw_response: response,
    valid: errors.length === 0,
    validation_errors: errors,
    input_token_count: response.usageMetadata?.promptTokenCount || null,
    output_token_count: response.usageMetadata?.candidatesTokenCount || null
  }
}];

const d = $input.first().json;
const r = d.dd_report;

const riskBadge = { low: 'LOW', medium: 'MEDIUM', high: 'HIGH', decline: 'DECLINE' }[r.risk_rating] || r.risk_rating;
const decisionBadge = { proceed: 'PROCEED', proceed_with_conditions: 'PROCEED WITH CONDITIONS', decline: 'DECLINE' }[r.recommended_decision] || r.recommended_decision;

const detailedAssessment = [
  ['Executive Summary', 'Top-line synthesis and authorisation scope', r.executive_summary],
  d.applicant_type === 'Individual' && r.fit_and_proper_assessment ? ['Fit and Proper', 'Competence, honesty/integrity, financial soundness', JSON.stringify(r.fit_and_proper_assessment)] : null,
  d.applicant_type === 'Fund' && r.fund_specific_findings ? ['Fund-Specific Findings', 'Mandate, structure, asset class, infrastructure, conflicts, insurance/tax, expertise', JSON.stringify(r.fund_specific_findings)] : null
].filter(Boolean);

const detailedRows = detailedAssessment.map(([item, what, assess]) => `| ${item} | ${what} | ${assess.replace(/\|/g, '/').slice(0, 500)} |`).join('
');

const conditionsRows = (r.conditions || []).map(c => `| ${c.severity} | ${c.condition} | ${c.owner} | ${c.deadline} |`).join('
') || '| _None_ | | | |';

const redFlagsMd = (r.red_flags || []).length
  ? r.red_flags.map(f => `- **[${f.severity.toUpperCase()}]** ${f.flag} (source: ${f.source})
  Evidence: ${f.evidence}${f.mitigation ? `
  Mitigation: ${f.mitigation}` : ''}`).join('
')
  : '_None identified._';

const orangeFlagsMd = (r.orange_flags || []).length
  ? r.orange_flags.map(f => `- ${f.flag} (source: ${f.source}) — ${f.evidence}`).join('
')
  : '_None identified._';

const outstandingMd = (r.outstanding_items || []).length ? r.outstanding_items.map(i => `- ${i}`).join('
') : '_None._';
const supervisionMd = (r.supervision_recommendations || []).length ? r.supervision_recommendations.map(i => `- ${i}`).join('
') : '_None._';

const undertakingsRows = (r.assumed_undertakings || []).map(u => `| ${u.undertaking} | ${u.source} | ${u.effective_date || 'TBD'} | ${u.breach_consequence || 'Not specified'} |`).join('
') || '| _None_ | | | |';

const sourcesRows = (r.sources_reviewed || []).map(s => `| ${s.id} | ${s.title} | ${s.type} | ${s.summary.slice(0, 200)} |`).join('
') || '| _None recorded_ | | | |';

const ts = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);
const reportPath = `/Applicants/${d.applicant_id}/06_DD_Report/dd_report_${ts}.md`;
const reportJsonPath = `/Applicants/${d.applicant_id}/06_DD_Report/dd_report_${ts}.json`;

const md = `# Due Diligence Report

**Case ID:** ${d.case_id}  
**Applicant:** ${d.applicant_name}  
**Applicant Type:** ${d.applicant_type}  
**Licence Target:** ${d.licence_target || 'Not specified'}  
**Authorisation Sought:** ${JSON.stringify(d.authorisation_sought)}${d.authorisation_assumed ? ' _(assumed — see note below)_' : ''}  
**Generated:** ${new Date().toISOString()}  
**Model:** gemini-2.5-flash (CR-03, full PLAN.md/SKILL.md prompt, generation_method=wf_cr03_async_full)

---

## Recommendation

| Risk Rating | Recommended Decision |
|---|---|
| ${riskBadge} | ${decisionBadge} |

## Legend

- **Red flag severities:** minor < moderate < serious < blocking
- **Condition severities:** low < medium < high < critical (critical = pre-LOA/pre-appointment/pre-capital-call/pre-launch gating)

## Executive Summary

${r.executive_summary}

---

## Detailed Assessment

| Item | What it covers | Assessment |
|---|---|---|
${detailedRows}

## Rationale

${r.rationale}

## Red Flags

${redFlagsMd}

## Orange Flags

${orangeFlagsMd}

## Outstanding Items

${outstandingMd}

## Conditions

| Severity | Condition | Owner | Deadline |
|---|---|---|---|
${conditionsRows}

## Assumed Undertakings

| Undertaking | Source | Effective Date | Breach Consequence |
|---|---|---|---|
${undertakingsRows}

## Supervision Recommendations

${supervisionMd}

## Sources Reviewed

| ID | Title | Type | Summary |
|---|---|---|---|
${sourcesRows}

---

_This report was generated by Alpha Node's WF-CR03 Async Report Generator (full PLAN.md/SKILL.md/PREFLIGHT fidelity, attempt ${d.attempt}). PDF rendering is a manual step — see 002 Claude Routines/CR-03 DD Report Generation/PLAN.md "PDF Generation". It must be reviewed and approved by a qualified senior officer before any decision is acted upon._
`;

return [{ json: { ...d, report_markdown: md, report_path: reportPath, report_json_path: reportJsonPath, report_timestamp: ts } }];
